import React from "react";

const HomePage = () => {
  return (
    <div style={styles.container}>
      {/* Üstteki Çizgiler ve Noktalar */}
      <div style={styles.topBar}>
        <div style={styles.dots}></div>
        <div style={styles.line}></div>
      </div>

      {/* İçerik Kutusu */}
      <div style={styles.contentBox}>
        {/* Sol Çizgi */}
        <div style={styles.sideLine}></div>

        {/* İçerik */}
        <div style={styles.mainContent}></div>

        {/* Sağ Çizgi */}
        <div style={styles.sideLine}></div>
      </div>

      {/* Alt Bar */}
      <div style={styles.bottomBar}></div>
    </div>
  );
};

// CSS Stilleri
const styles = {
  container: {
    position: "relative",
    maxWidth: "1024px",
    margin: "50px auto",
    background: "#FFFFFF",
    borderRadius: "10px",
    overflow: "hidden",
  },
  topBar: {
    display: "flex",
    justifyContent: "space-between",
    alignItems: "center",
    padding: "10px 20px",
    backgroundColor: "#FFFFFF",
  },
  dots: {
    width: "30px",
    height: "10px",
    backgroundColor: "#293349",
    borderRadius: "5px",
  },
  line: {
    width: "150px",
    height: "4px",
    backgroundColor: "#293349",
  },
  contentBox: {
    display: "flex",
    flexDirection: "row",
    alignItems: "center",
    justifyContent: "center",
    padding: "20px",
    backgroundColor: "#293349",
    border: "15px solid #00C26D",
    height: "400px",
  },
  sideLine: {
    width: "15px",
    height: "100%",
    backgroundColor: "#293349",
  },
  mainContent: {
    flexGrow: 1,
    height: "100%",
    backgroundColor: "#FFFFFF",
    borderRadius: "10px",
  },
  bottomBar: {
    height: "30px",
    backgroundColor: "#293349",
    marginTop: "10px",
  },
};

export default HomePage;
